/**
 * pyrepr.mjs — Python 3 `repr()` for `bytes` and `str`, plus `print()` semantics.
 *
 * Faithful ports of:
 *   - CPython Objects/bytesobject.c :: bytes_repr()
 *   - CPython Objects/unicodeobject.c :: unicode_repr()
 *   - CPython Objects/unicodectype.c :: Py_UNICODE_ISPRINTABLE()  (str.isprintable)
 *
 * Node.js ESM, zero dependencies, no punycode / no URL machinery.
 */

const BACKSLASH = 0x5c;
const SQUOTE = 0x27; // '
const DQUOTE = 0x22; // "
const TAB = 0x09;
const LF = 0x0a;
const CR = 0x0d;
const SPACE = 0x20;
const DEL = 0x7f;

/** Lowercase two-digit hex, e.g. 10 -> "0a". */
const hex2 = (n) => n.toString(16).padStart(2, '0');
/** Lowercase hex padded to `width` digits. */
const hexPad = (n, width) => n.toString(16).padStart(width, '0');

// ---------------------------------------------------------------------------
// str.isprintable()
// ---------------------------------------------------------------------------

/**
 * CPython's makeunicodedata.py marks a codepoint printable as:
 *
 *   printable = NOT in general categories Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs
 *               EXCEPT that U+0020 SPACE is printable.
 *
 * We express that as a single precompiled RegExp over Unicode property escapes
 * rather than a generated lookup table. `\p{Cn}` (General_Category=Unassigned)
 * is supported by V8; `\P{Assigned}` is the documented equivalent and is used
 * as a fallback for engines that reject the `Cn` alias.
 */
const NONPRINTABLE_RE = (() => {
  const props = ['Cc', 'Cf', 'Cs', 'Co', 'Cn', 'Zl', 'Zp', 'Zs'];
  try {
    return new RegExp(`^[${props.map((p) => `\\p{${p}}`).join('')}]$`, 'u');
  } catch {
    // Older engines may not accept the `Cn` alias; `\P{Assigned}` is identical
    // in meaning (everything with General_Category=Unassigned).
    const rest = props.filter((p) => p !== 'Cn').map((p) => `\\p{${p}}`).join('');
    return new RegExp(`^[${rest}\\P{Assigned}]$`, 'u');
  }
})();

/**
 * Memo for non-ASCII codepoints. Classification is pure, and repr() over a long
 * string tends to revisit the same codepoints, so caching keeps us off the
 * regex engine in the common case. Populated lazily — no giant static table.
 */
const printableCache = new Map();

/**
 * Python's `str.isprintable()` rule, evaluated for a single codepoint.
 *
 * @param {number} cp - Unicode codepoint (0 .. 0x10FFFF). Lone surrogates
 *   (0xD800..0xDFFF) are accepted and reported non-printable, matching CPython,
 *   which permits them inside `str`.
 * @returns {boolean} true if Python would emit the character literally.
 */
export function isPrintable(cp) {
  // Fast path: printable ASCII, including SPACE (the sole Zs exception).
  if (cp >= SPACE && cp < DEL) return true;
  // Fast path: C0 controls and DEL are Cc, never printable.
  if (cp < SPACE || cp === DEL) return false;

  const cached = printableCache.get(cp);
  if (cached !== undefined) return cached;

  // String.fromCodePoint happily produces a lone surrogate, which `\p{Cs}`
  // matches under the /u flag, so no special-casing is required here.
  const result = !NONPRINTABLE_RE.test(String.fromCodePoint(cp));
  printableCache.set(cp, result);
  return result;
}

// ---------------------------------------------------------------------------
// bytes repr
// ---------------------------------------------------------------------------

/** Coerce the accepted input shapes to a Uint8Array without copying when possible. */
function toBytes(bytes) {
  if (bytes instanceof Uint8Array) return bytes;
  if (bytes instanceof ArrayBuffer) return new Uint8Array(bytes);
  if (ArrayBuffer.isView(bytes)) {
    return new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  }
  if (Array.isArray(bytes)) return Uint8Array.from(bytes);
  throw new TypeError('bytesRepr: expected Uint8Array, ArrayBuffer view, or array of 0..255');
}

/**
 * Python 3 `repr()` of a `bytes` object.
 *
 * @param {Uint8Array|ArrayBuffer|ArrayBufferView|number[]} bytes
 * @returns {string} e.g. "b'xn--caf-dma'"
 */
export function bytesRepr(bytes) {
  const buf = toBytes(bytes);

  // Quote selection (CPython's "smart quotes"): single quotes by default;
  // switch to double quotes only when a ' is present and a " is not.
  let hasSquote = false;
  let hasDquote = false;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === SQUOTE) hasSquote = true;
    else if (buf[i] === DQUOTE) hasDquote = true;
  }
  const quote = hasSquote && !hasDquote ? DQUOTE : SQUOTE;
  const quoteChar = String.fromCharCode(quote);

  const out = ['b', quoteChar];
  for (let i = 0; i < buf.length; i++) {
    const c = buf[i];
    // Order matters and mirrors bytes_repr(): quote/backslash first, then the
    // three named whitespace escapes, then the generic \xNN range.
    if (c === quote || c === BACKSLASH) out.push('\\', String.fromCharCode(c));
    else if (c === TAB) out.push('\\t');
    else if (c === LF) out.push('\\n');
    else if (c === CR) out.push('\\r');
    else if (c < SPACE || c >= DEL) out.push('\\x', hex2(c));
    else out.push(String.fromCharCode(c));
  }
  out.push(quoteChar);
  return out.join('');
}

// ---------------------------------------------------------------------------
// str repr
// ---------------------------------------------------------------------------

/**
 * Escape a non-printable codepoint the way unicode_repr() does:
 * \xNN below 0x100, \uNNNN below 0x10000, \UNNNNNNNN above.
 */
function escapeCodepoint(cp) {
  if (cp < 0x100) return `\\x${hexPad(cp, 2)}`;
  if (cp < 0x10000) return `\\u${hexPad(cp, 4)}`;
  return `\\U${hexPad(cp, 8)}`;
}

/**
 * Python 3 `repr()` of a `str`.
 *
 * Iterates by codepoint, so astral characters count as one unit and are emitted
 * either literally or as a single `\UNNNNNNNN` escape (never as a surrogate pair).
 *
 * @param {string} s
 * @returns {string}
 */
export function strRepr(s) {
  const str = String(s);

  // Quote selection, identical policy to bytes: prefer ', use " only when the
  // string contains ' but no ".
  const hasSquote = str.includes("'");
  const hasDquote = str.includes('"');
  const quoteChar = hasSquote && !hasDquote ? '"' : "'";

  const out = [quoteChar];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (ch === quoteChar || cp === BACKSLASH) out.push('\\', ch);
    else if (cp === TAB) out.push('\\t');
    else if (cp === LF) out.push('\\n');
    else if (cp === CR) out.push('\\r');
    else if (isPrintable(cp)) out.push(ch);
    else out.push(escapeCodepoint(cp));
  }
  out.push(quoteChar);
  return out.join('');
}

// ---------------------------------------------------------------------------
// print() semantics
// ---------------------------------------------------------------------------

/**
 * Tracks the tail of the stdout write queue so callers can await a real flush.
 * Node keeps the event loop alive for a pending stdout pipe write, so a normal
 * exit is already safe; this exists for the `process.exit()` / explicit-drain case.
 */
let pendingFlush = Promise.resolve();

/**
 * Python's `print(text)`: write `text` followed by a newline to stdout as UTF-8.
 *
 * @param {string} text
 */
export function printLine(text) {
  const chunk = Buffer.from(`${text}\n`, 'utf8');
  pendingFlush = new Promise((resolve) => {
    // The write callback fires once the chunk has been handed to the OS, which
    // is what "flushed" means for a pipe, a file, or a TTY alike.
    if (!process.stdout.write(chunk, resolve)) {
      // Backpressure: the callback still fires after drain, so nothing extra
      // is needed here beyond not dropping the promise.
    }
  });
}

/**
 * Resolves once everything handed to {@link printLine} has reached the OS.
 * Await this before calling `process.exit()`, which otherwise truncates
 * asynchronous stdout (pipes and sockets).
 *
 * @returns {Promise<void>}
 */
export async function flushStdout() {
  await pendingFlush;
}

/**
 * pyrepr-selftest.mjs — self-test for /tmp/wf/pyrepr.mjs
 *
 * Runs a fixed set of golden assertions, then (when a local python3 exists)
 * a differential fuzz against real CPython repr() for both str and bytes.
 *
 *   node /tmp/wf/pyrepr-selftest.mjs
 */

import { spawnSync } from 'node:child_process';
import { bytesRepr, strRepr, isPrintable, printLine, flushStdout } from './pyrepr.mjs';

let passed = 0;
const failures = [];

function eq(label, actual, expected) {
  if (actual === expected) {
    passed++;
  } else {
    failures.push(`${label}\n    expected: ${JSON.stringify(expected)}\n    actual:   ${JSON.stringify(actual)}`);
  }
}

const enc = new TextEncoder();
const b = (s) => enc.encode(s);

// ---------------------------------------------------------------------------
// 1. Golden cases named in the task
// ---------------------------------------------------------------------------

// repr('ab‌cd') -> 'ab‌cd' with the ZWNJ escaped as backslash-u-2-0-0-c.
// Built character-by-character so the expectation cannot itself contain a real ZWNJ.
const ZWNJ_EXPECTED = ["'", 'a', 'b', '\\', 'u', '2', '0', '0', 'c', 'c', 'd', "'"].join('');
eq("strRepr('ab<ZWNJ>cd')", strRepr('ab‌cd'), ZWNJ_EXPECTED);

// Devanagari stays literal, ZWNJ is escaped.
eq(
  "strRepr('\\u0928<ZWNJ>\\u093f')",
  strRepr('न‌ि'),
  "'न" + '\\u200c' + "ि'",
);

// bytes repr of an A-label.
eq("bytesRepr(b'xn--caf-dma')", bytesRepr(b('xn--caf-dma')), "b'xn--caf-dma'");

// ---------------------------------------------------------------------------
// 2. isPrintable spot checks
// ---------------------------------------------------------------------------

const printableChecks = [
  [0x20, true, 'SPACE is the one printable Zs'],
  [0x41, true, 'A'],
  [0x7e, true, '~'],
  [0x00, false, 'NUL (Cc)'],
  [0x09, false, 'TAB (Cc)'],
  [0x1f, false, 'US (Cc)'],
  [0x7f, false, 'DEL (Cc)'],
  [0x80, false, 'C1 control (Cc)'],
  [0x9f, false, 'C1 control (Cc)'],
  [0xa0, false, 'NBSP (Zs)'],
  [0xad, false, 'SOFT HYPHEN (Cf)'],
  [0x200c, false, 'ZWNJ (Cf)'],
  [0x2028, false, 'LINE SEPARATOR (Zl)'],
  [0x2029, false, 'PARAGRAPH SEPARATOR (Zp)'],
  [0x3000, false, 'IDEOGRAPHIC SPACE (Zs)'],
  [0xd800, false, 'lone high surrogate (Cs)'],
  [0xdfff, false, 'lone low surrogate (Cs)'],
  [0xe000, false, 'private use (Co)'],
  [0x0378, false, 'unassigned (Cn)'],
  [0x0928, true, 'DEVANAGARI NA'],
  [0x093f, true, 'DEVANAGARI VOWEL SIGN I (Mc)'],
  [0x0301, true, 'COMBINING ACUTE (Mn) is printable in Python'],
  [0x1f600, true, 'emoji (So)'],
  [0xe0001, false, 'LANGUAGE TAG (Cf, astral)'],
  [0x10ffff, false, 'noncharacter (Cn)'],
];
for (const [cp, want, why] of printableChecks) {
  eq(`isPrintable(U+${cp.toString(16).toUpperCase().padStart(4, '0')}) ${why}`, isPrintable(cp), want);
}

// ---------------------------------------------------------------------------
// 3. Quote selection + escaping, both types
// ---------------------------------------------------------------------------

eq('strRepr empty', strRepr(''), "''");
eq('strRepr plain', strRepr('abc'), "'abc'");
eq('strRepr squote only -> double quotes', strRepr("it's"), '"it\'s"');
eq('strRepr dquote only -> single quotes', strRepr('say "hi"'), '\'say "hi"\'');
eq('strRepr both quotes -> single, escape squote', strRepr('it\'s "x"'), '\'it\\\'s "x"\'');
eq('strRepr backslash', strRepr('a\\b'), "'a\\\\b'");
eq('strRepr tab/nl/cr', strRepr('a\tb\nc\rd'), "'a\\tb\\nc\\rd'");
eq('strRepr other C0 -> \\xNN', strRepr('\x00\x01\x1f'), "'\\x00\\x01\\x1f'");
eq('strRepr DEL + C1', strRepr('\x7f\x85'), "'\\x7f\\x85'");
eq('strRepr NBSP', strRepr(' '), "'\\xa0'");
eq('strRepr astral printable stays literal', strRepr('\u{1f600}'), "'\u{1f600}'");
eq('strRepr astral non-printable -> \\U', strRepr('\u{e0001}'), "'\\U000e0001'");
eq('strRepr lone surrogate -> \\uNNNN', strRepr('\ud800'), "'\\ud800'");
eq('strRepr non-ASCII printable literal', strRepr('café'), "'café'");

eq('bytesRepr empty', bytesRepr(new Uint8Array(0)), "b''");
eq('bytesRepr squote only -> double quotes', bytesRepr(b("it's")), 'b"it\'s"');
eq('bytesRepr dquote only -> single quotes', bytesRepr(b('say "hi"')), 'b\'say "hi"\'');
eq('bytesRepr both quotes -> single, escape squote', bytesRepr(b('it\'s "x"')), 'b\'it\\\'s "x"\'');
eq('bytesRepr backslash', bytesRepr(b('a\\b')), "b'a\\\\b'");
eq('bytesRepr tab/nl/cr', bytesRepr(b('a\tb\nc\rd')), "b'a\\tb\\nc\\rd'");
eq('bytesRepr high bytes', bytesRepr([0x00, 0x1f, 0x7e, 0x7f, 0x80, 0xff]), "b'\\x00\\x1f~\\x7f\\x80\\xff'");
eq('bytesRepr utf8 of café', bytesRepr(b('café')), "b'caf\\xc3\\xa9'");
eq('bytesRepr accepts plain array', bytesRepr([104, 105]), "b'hi'");

// ---------------------------------------------------------------------------
// 4. Differential fuzz against real CPython
// ---------------------------------------------------------------------------

const PY_DRIVER = `
import sys, json
data = json.load(sys.stdin)
out = []
for kind, payload in data:
    if kind == 's':
        out.append(repr(''.join(chr(c) for c in payload)))
    else:
        out.append(repr(bytes(payload)))
print(json.dumps(out))
`;

function pythonReprs(cases) {
  const r = spawnSync('python3', ['-c', PY_DRIVER], {
    input: JSON.stringify(cases),
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  if (r.status !== 0) return null;
  return JSON.parse(r.stdout);
}

/** Build a JS string from an array of codepoints (surrogates included). */
const fromCps = (cps) => cps.map((c) => String.fromCodePoint(c)).join('');

function runDifferential() {
  const probe = spawnSync('python3', ['-c', 'print(1)'], { encoding: 'utf8' });
  if (probe.status !== 0) {
    console.log('  (skipped: no local python3)');
    return;
  }
  const ver = spawnSync('python3', ['-c', 'import sys,unicodedata;print(sys.version.split()[0], unicodedata.unidata_version)'], { encoding: 'utf8' }).stdout.trim();
  console.log(`  CPython ${ver}   |   Node ${process.versions.node} ICU ${process.versions.icu} Unicode ${process.versions.unicode}`);

  const cases = [];

  // (a) Every codepoint in the BMP plus a stride through the astral planes,
  //     one codepoint per str case. This is the real test of isPrintable().
  for (let cp = 0; cp <= 0xffff; cp++) cases.push(['s', [cp]]);
  for (let cp = 0x10000; cp <= 0x10ffff; cp += 7) cases.push(['s', [cp]]);

  // (b) Every single byte value as a 1-byte bytes object, plus all 2-byte
  //     combinations of the "interesting" bytes (quotes, escapes, boundaries).
  for (let v = 0; v <= 0xff; v++) cases.push(['b', [v]]);
  const interesting = [0x00, 0x09, 0x0a, 0x0d, 0x1f, 0x20, 0x22, 0x27, 0x5c, 0x7e, 0x7f, 0x80, 0xff];
  for (const x of interesting) for (const y of interesting) cases.push(['b', [x, y]]);

  // (c) Random multi-codepoint strings, weighted toward escape-triggering chars.
  let seed = 0x2f6e2b1;
  const rnd = () => {
    // xorshift32, so the corpus is deterministic across runs.
    seed ^= seed << 13; seed >>>= 0;
    seed ^= seed >>> 17;
    seed ^= seed << 5; seed >>>= 0;
    return seed / 0x100000000;
  };
  const pool = [0x27, 0x22, 0x5c, 0x09, 0x0a, 0x0d, 0x20, 0x41, 0xa0, 0xad, 0x200c, 0x2028, 0x3000, 0x0928, 0x093f, 0xd800, 0xe000, 0x1f600, 0xe0001];
  for (let i = 0; i < 4000; i++) {
    const len = 1 + Math.floor(rnd() * 8);
    const cps = [];
    for (let j = 0; j < len; j++) {
      cps.push(rnd() < 0.7 ? pool[Math.floor(rnd() * pool.length)] : Math.floor(rnd() * 0x110000));
    }
    cases.push(['s', cps]);
  }
  // (d) Random byte strings.
  for (let i = 0; i < 2000; i++) {
    const len = 1 + Math.floor(rnd() * 10);
    const bytes = [];
    for (let j = 0; j < len; j++) {
      bytes.push(rnd() < 0.5 ? interesting[Math.floor(rnd() * interesting.length)] : Math.floor(rnd() * 256));
    }
    cases.push(['b', bytes]);
  }

  // Chunk so we never hand python an unreasonable stdin blob.
  const CHUNK = 20000;
  let diffs = 0;
  const samples = [];
  for (let start = 0; start < cases.length; start += CHUNK) {
    const slice = cases.slice(start, start + CHUNK);
    const expected = pythonReprs(slice);
    if (!expected) {
      failures.push('differential: python3 driver failed');
      return;
    }
    for (let i = 0; i < slice.length; i++) {
      const [kind, payload] = slice[i];
      const got = kind === 's' ? strRepr(fromCps(payload)) : bytesRepr(payload);
      if (got !== expected[i]) {
        diffs++;
        if (samples.length < 25) {
          samples.push(`    ${kind} ${JSON.stringify(payload.map((c) => 'U+' + c.toString(16)))} py=${expected[i]} js=${got}`);
        }
      } else {
        passed++;
      }
    }
  }
  console.log(`  differential cases: ${cases.length}, mismatches: ${diffs}`);
  if (diffs) failures.push(`differential mismatches: ${diffs}\n${samples.join('\n')}`);
}

// ---------------------------------------------------------------------------
// 5. printLine round-trip (UTF-8 correctness) in a child process
// ---------------------------------------------------------------------------

function testPrintLine() {
  const child = spawnSync(process.execPath, ['--input-type=module', '-e', `
    import { printLine, strRepr, bytesRepr, flushStdout } from '/tmp/wf/pyrepr.mjs';
    printLine('caf\\u00e9');
    printLine('\\u0928\\u200c\\u093f');
    printLine('\\u{1f600}');
    printLine(strRepr('ab\\u200ccd'));
    printLine(bytesRepr(new TextEncoder().encode('xn--caf-dma')));
    await flushStdout();
    process.exit(0);
  `], { encoding: 'buffer' });

  const outText = child.stdout.toString('utf8');
  const pyOut = spawnSync('python3', ['-c', `
print('caf\\u00e9')
print('\\u0928\\u200c\\u093f')
print('\\U0001f600')
print(repr('ab\\u200ccd'))
print(repr(b'xn--caf-dma'))
`], { encoding: 'buffer', env: { ...process.env, PYTHONIOENCODING: 'utf-8' } });

  eq('printLine byte-for-byte matches python print()', child.stdout.toString('hex'), pyOut.stdout.toString('hex'));
  // Also confirm the last line survived the explicit process.exit(0) after flush.
  eq('printLine flushed final line before exit', outText.trimEnd().split('\n').pop(), "b'xn--caf-dma'");
}

// ---------------------------------------------------------------------------

console.log('pyrepr self-test');
runDifferential();
testPrintLine();

if (failures.length) {
  console.log(`\nFAIL — ${failures.length} failing group(s), ${passed} assertions passed\n`);
  for (const f of failures) console.log('  ' + f);
  process.exitCode = 1;
} else {
  console.log(`\nOK — ${passed} assertions passed`);
}

